/* ============================================================================
   Claude Design — Dashboard Design System
   Tailwind v4 + shadcn/ui token bridge. Synced from the canonical tokens.css.

   Layers:
   - :root            actual values (swap under .dark later, same names)
   - @theme inline    exposes tokens as bg-, text-, rounded-, shadow- utilities
   Components reference semantic utilities only — never raw hex.
   ========================================================================== */

@import "tailwindcss";
@import url("https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap");
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

/* ---- Actual values --------------------------------------------------------- */
:root {
  --background: #ffffff;
  --foreground: #1d1d1f;
  --card: #ffffff;
  --card-foreground: #1d1d1f;
  --popover: #ffffff;
  --popover-foreground: #1d1d1f;

  --primary: #0071e3;
  --primary-hover: #0068ce;
  --primary-active: #0059b2;
  --primary-foreground: #ffffff;

  --secondary: #f5f5f7;
  --secondary-hover: #e8e8ed;
  --secondary-foreground: #1d1d1f;

  --muted: #f5f5f7;
  --muted-foreground: #6e6e73;
  --text-tertiary: #86868b;

  --accent: #e8f1fd;
  --accent-foreground: #0071e3;

  --destructive: #d70015;
  --destructive-hover: #b80012;
  --destructive-foreground: #ffffff;

  --border: #e8e8ed;
  --input: #d2d2d7;
  --ring: #0071e3;

  --success: #248a3d;
  --success-foreground: #ffffff;
  --success-subtle: #e9f6ee;
  --warning: #b25000;
  --warning-foreground: #ffffff;
  --warning-subtle: #fdf0e6;
  --error: #d70015;
  --error-foreground: #ffffff;
  --error-subtle: #fde8e9;
  --info: #0071e3;
  --info-foreground: #ffffff;
  --info-subtle: #e8f1fd;

  /* Categorical series colors. Hue carries the meaning, so they are chosen to
     stay separable under protanopia, deuteranopia and tritanopia as well as
     normal vision (min ΔE2000 9.0 across all four), and to hold at least 3:1
     against --card for WCAG 1.4.11 non-text contrast. */
  --chart-1: #0071e3;
  --chart-2: #aeaeb2;
  --chart-3: #248a3d;
  --chart-4: #b25000;
  --chart-5: #7629a3;
  --chart-6: #0096ad;

  /* Density — compact set for dense tables/regions */
  --row-height: 56px;
  --row-height-compact: 44px;
  --cell-pad-x: 16px;
  --cell-pad-y: 8px;
}

/* ---- Dark mode scaffold (light-only v1) -----------------------------------
   Fill these in later using the SAME names. No downstream renames required.
.dark {
  --background: #000000;
  --foreground: #ffffff;
  --card: #1d1d1f;
  --muted: #1d1d1f;
  --border: #2c2c2e;
  --chart-1: #0a84ff;
  --chart-2: #98989d;
  --chart-3: #30d158;
  --chart-4: #ff9f0a;
  --chart-5: #bf5af2;
  --chart-6: #40c8e0;
  ...
}
--------------------------------------------------------------------------- */

/* ---- Tailwind theme bridge ------------------------------------------------- */
@theme inline {
  --font-sans: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --font-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);

  --color-primary: var(--primary);
  --color-primary-hover: var(--primary-hover);
  --color-primary-active: var(--primary-active);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-hover: var(--secondary-hover);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-text-tertiary: var(--text-tertiary);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-hover: var(--destructive-hover);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);

  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-success-subtle: var(--success-subtle);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-warning-subtle: var(--warning-subtle);
  --color-error: var(--error);
  --color-error-foreground: var(--error-foreground);
  --color-error-subtle: var(--error-subtle);
  --color-info: var(--info);
  --color-info-foreground: var(--info-foreground);
  --color-info-subtle: var(--info-subtle);

  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-chart-6: var(--chart-6);

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --radius-xl: 20px;

  --shadow-xs: 0 1px 2px rgba(0, 0, 0, 0.04);
  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.06), 0 1px 2px rgba(0, 0, 0, 0.04);
  --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.08);
  --shadow-lg: 0 12px 32px rgba(0, 0, 0, 0.12);
  --shadow-xl: 0 24px 64px rgba(0, 0, 0, 0.16);

  --ease-standard: cubic-bezier(0.4, 0, 0.2, 1);
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);
}

@layer base {
  * {
    border-color: var(--border);
  }
  body {
    background-color: var(--background);
    color: var(--foreground);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }
}
